const crypto = require('crypto');

// A Discord public key beegetve, NEM env valtozobol.
//
// Ok: a Code node kulon task-runner konteneben fut, ami teljesen elzarja az
// env-hozzaferest ("process.env nem elerheto"), es az n8n Variables funkcio
// licenckoteles ezen a peldanyon. Egyik ut sem jarhato.
//
// Ez biztonsagos: a public key NEM titok. A Developer Portal nyilvanosan
// mutatja, es csak alairas-ELLENORZESRE valo, nem alairasra - a birtoklasa
// senkit nem tesz kepesse keres hamisitasara. A bot token az igazi titok,
// az az n8n credentialban van.
//
// Ha uj Discord alkalmazast hozol letre, ezt a sort kell atirni.
const PUBLIC_KEY = 'a501a7fa9d9249ecda08991c0c6807faac9ef8a13f89c7f25d9b9bb8d3f6ac8c';

const headers = $json.headers || {};
const sig = headers['x-signature-ed25519'];
const ts = headers['x-signature-timestamp'];

// A nyers testre van szukseg, nem a parse-olt JSON-ra: az alairas a PONTOS
// byte-sorozatra vonatkozik, ezert egy ujraszerializalt JSON nem ellenorizne.
//
// A webhook node (rawBody: true) a nyers testet az item BINARY mezojebe teszi
// base64-kent, nem a json.rawBody-ba. A $binary globalis "Run Once for All
// Items" modban nem a vart itemre mutat, ezert $input.first()-bol olvassuk.
let rawBody = '';
const first = $input.first();
if (first && first.binary && first.binary.data && first.binary.data.data) {
  rawBody = Buffer.from(first.binary.data.data, 'base64').toString('utf8');
} else if ($json.rawBody !== undefined && $json.rawBody !== null) {
  rawBody = Buffer.isBuffer($json.rawBody) ? $json.rawBody.toString('utf8') : String($json.rawBody);
} else if ($json.body !== undefined) {
  // Vegso mentsvar: ujraszerializaljuk. Ez CSAK akkor egyezik, ha a Discord
  // byte-pontosan ugyanigy szerializalt - ne tamaszkodjunk ra.
  rawBody = JSON.stringify($json.body);
}

const fail = (reason) => [{ json: {
  ok: false, http_status: 401, reason,
  response: { error: 'invalid request signature' },
}}];

if (!PUBLIC_KEY) return fail('DISCORD_PUBLIC_KEY env valtozo nincs beallitva');
if (!sig || !ts) return fail('hianyzo alairas fejlec');
if (!rawBody) return fail('hianyzo nyers test');

let verified = false;
try {
  // A Discord nyers 32 byte-os hex kulcsot ad. Ebbol SPKI DER kulcsot epitunk.
  const DER_PREFIX = Buffer.from('302a300506032b6570032100', 'hex');
  const key = crypto.createPublicKey({
    key: Buffer.concat([DER_PREFIX, Buffer.from(PUBLIC_KEY, 'hex')]),
    format: 'der', type: 'spki',
  });
  verified = crypto.verify(null, Buffer.from(ts + rawBody, 'utf8'), key, Buffer.from(sig, 'hex'));
} catch (e) {
  return fail('alairas ellenorzes hiba: ' + String(e.message).slice(0, 80));
}
if (!verified) return fail('ervenytelen alairas');

let body;
try { body = JSON.parse(rawBody); } catch (e) { return fail('hibas JSON'); }

// type 1 = PING. A Discord ezzel ellenorzi a vegpontot; type 1-gyel kell valaszolni.
if (body.type === 1) {
  return [{ json: { ok: true, http_status: 200, is_ping: true, response: { type: 1 } } }];
}

// type 2 = APPLICATION_COMMAND (slash parancs)
if (body.type !== 2) {
  return [{ json: { ok: true, http_status: 200, is_other: true,
    response: { type: 4, data: { content: 'Nem tamogatott interakcio.', flags: 64 } } } }];
}

const data = body.data || {};
const name = String(data.name || '').toLowerCase();
const opts = {};
for (const o of (data.options || [])) opts[o.name] = o.value;

// Ki inditotta? A Discord DM-ben body.user, szerveren body.member.user.
const user = (body.member && body.member.user) || body.user || {};
const userId = user.id || null;

// Hozzaferes-vedelem: ha a DISCORD_USER_ID be van allitva, csak az hasznalhatja.
// Opcionalis hozzaferes-szures. Ures = barki hasznalhatja, aki eleri a
// szervert. Sajat szerveren ez rendben van; ha megosztod, ird ide a sajat
// Discord user ID-dat (Developer Mode -> jobb klikk a nevedre -> Copy User ID).
const allowed = '';
if (allowed && String(userId) !== String(allowed).trim()) {
  return [{ json: { ok: true, http_status: 200, denied: true,
    response: { type: 4, data: { content: 'Ez a bot nem a te hasznalatodra van beallitva.', flags: 64 } } } }];
}

const out = { ok: true, http_status: 200, user_id: userId, command: name };

if (name === 'help' || name === 'sugo') return [{ json: { ...out, command: 'help' } }];
if (name === 'slate' || name === 'kinalat') return [{ json: { ...out, command: 'slate' } }];

if (name !== 'szelveny' && name !== 'slip') {
  return [{ json: { ...out, error: 'Ismeretlen parancs: /' + name } }];
}

const target = Number(String(opts.cel !== undefined ? opts.cel : opts.target).replace(',', '.'));
if (!Number.isFinite(target) || target <= 1) {
  return [{ json: { ...out, error: 'Ervenytelen cel-odds. Szam kell, 1-nel nagyobb.' } }];
}
if (target > 10000) {
  return [{ json: { ...out, error: 'A cel tul nagy. 10000x alatt maradj.' } }];
}

let maxLegs = 4, minLegOdds = 1.30;
// Idoablak: hany oran belul kezdodjon a meccs. A "mikor" opcio szoveges
// ertekei kenyelmi rovidites; az "orak" szam szabadon allithato.
let windowHours = null;
const WINDOW = { ma: 'today', today: 'today', holnap: 36, tomorrow: 36,
                 ma_este: 12, hetvege: 96, weekend: 96 };
if (opts.max !== undefined) {
  const v = Number(opts.max);
  if (Number.isFinite(v)) maxLegs = Math.max(1, Math.min(8, Math.round(v)));
}
if (opts.min !== undefined) {
  const v = Number(String(opts.min).replace(',', '.'));
  if (Number.isFinite(v) && v >= 1) minLegOdds = v;
}
if (opts.mikor !== undefined) {
  const key = String(opts.mikor).toLowerCase().trim();
  if (WINDOW[key] !== undefined) windowHours = WINDOW[key];
}
if (opts.orak !== undefined) {
  const v = Number(opts.orak);
  if (Number.isFinite(v) && v > 0) windowHours = Math.min(240, v);
}

return [{ json: { ...out, command: 'szelveny', target, maxLegs, minLegOdds, windowHours } }];

// WF-B / "Build Response" — parancs -> szelveny.
// A szelvenyepito algoritmus lokalisan tesztelve lett, mielott ide kerult.

// ---------- szelvenyepito ----------
function buildSlip(pool, opts) {
  const T = opts.target;
  const maxLegs = opts.maxLegs || 4;
  const minLegOdds = opts.minLegOdds || 1.30;
  const maxLegOdds = opts.maxLegOdds || 5.00;
  const tol = opts.tolerance || 0.12;
  const POOL_CAP = opts.poolCap || 40;

  let cand = pool.filter(l =>
    l.news_flag !== 'veto' &&
    l.confidence !== 'ALACSONY' &&
    l.tippmix_odds >= minLegOdds &&
    l.model_prob > 0
  );
  if (!cand.length) return { ok: false, reason: 'no_candidates' };

  // Minoseg = modell-valoszinuseg + bizalmi bonusz. NEM a modell-piac elteres:
  // meres szerint az elteresre szurni hibat szur, nem tudast.
  const confBonus = c => (c === 'MAGAS' ? 0.06 : c === 'KOZEPES' ? 0.02 : 0);
  cand.forEach(l => { l._q = l.model_prob + confBonus(l.confidence) - (l.news_flag === 'warn' ? 0.03 : 0); });
  cand.sort((a, b) => b._q - a._q);

  // Retegzett vagas odds-savonkent. Tiszta minoseg szerinti vagas kiszorna az
  // osszes magas oddsu labat, es a nagy cel-oddsok elerhetetlenne valnanak.
  const BANDS = [[1.0, 1.6], [1.6, 2.2], [2.2, 3.2], [3.2, 5.0], [5.0, Infinity]];
  const perBand = Math.max(4, Math.ceil(POOL_CAP / BANDS.length));
  const picked = [];
  for (const b of BANDS) {
    picked.push(...cand.filter(l => l.tippmix_odds >= b[0] && l.tippmix_odds < b[1]).slice(0, perBand));
  }
  cand = picked.sort((a, b) => b._q - a._q);
  if (!cand.length) return { ok: false, reason: 'no_candidates' };

  // Minimum 2 lab: aki szelvenyt ker, tobb labra gondol - egy lab sima fogadas.
  // Ha 2 labbal nem jon ki a cel, a lenti fallback ad 1 labas megoldast.
  const minLegs = opts.minLegs || 2;
  const lo = T * (1 - tol), hi = T * (1 + tol);

  // PUHA ODDS-PLAFON: egy kereso-menet adott plafonnal. Azert kulon fuggveny,
  // hogy ketszer futtathassuk: eloszor a plafonnal, aztan nelkule.
  // Miert kell plafon: (1) a tippmixRatio() kalibracio csak 1.3-6.0 kozott
  // mert, fole extrapolal; (2) a modell rangsora forditva mukodik
  // (vs_human.js: legjobb negyed -17.7%, legrosszabb +1.4%), tehat magas
  // oddsu lab valasztasaban nem bizhatunk.
  const search = (cap) => {
    const pool2 = cand.filter(l => l.tippmix_odds <= cap);
    if (!pool2.length) return null;

    // A maxOdds a SZUKITETT listan szamolodik: alacsonyabb felso hatar,
    // tehat tobb lab kell ugyanahhoz a celhoz. Pont ez a kivant hatas.
    const maxOdds = Math.max(...pool2.map(l => l.tippmix_odds));
    const nMin = Math.max(minLegs, Math.ceil(Math.log(T) / Math.log(maxOdds)));
    if (nMin > maxLegs) return { failed: 'target_too_high', nMin, maxLegs, maxOdds };

    // n novekvo sorrendben. Az ELSO n, amin van megoldas, nyer — mert a margo
    // labankent szorzodik: 2 lab ~86%-ot tart meg, 3 lab ~79%-ot, 6 lab ~63%-ot.
    for (let n = nMin; n <= maxLegs; n++) {
      const found = [];
      const dfs = (start, chosen, prod, used) => {
        if (found.length >= 400) return;
        if (chosen.length === n) {
          if (prod >= lo && prod <= hi) found.push({ legs: chosen.slice(), prod });
          return;
        }
        const remaining = n - chosen.length;
        for (let i = start; i < pool2.length; i++) {
          if (pool2.length - i < remaining) break;
          const l = pool2[i];
          if (used.has(l.event_id)) continue;        // egy meccs = egy lab
          const p = prod * l.tippmix_odds;
          if (p * Math.pow(maxOdds, remaining - 1) < lo) continue;
          if (p > hi) continue;
          used.add(l.event_id); chosen.push(l);
          dfs(i + 1, chosen, p, used);
          chosen.pop(); used.delete(l.event_id);
        }
      };
      dfs(0, [], 1, new Set());
      if (found.length) {
        for (const f of found) {
          const jointP = f.legs.reduce((a, l) => a * l.model_prob, 1);
          const hiCount = f.legs.filter(l => l.confidence === 'MAGAS').length;
          const drift = Math.abs(f.prod - T) / T;
          f.score = jointP * (1 + 0.05 * hiCount) * (1 - drift);
          f.jointP = jointP;
        }
        found.sort((a, b) => b.score - a.score);
        const winner = found[0]; winner.n = n;
        return winner;
      }
    }
    return null;
  };

  // Elso menet: csak a plafon alatti labak.
  let best = null, relaxed = false, capFail = null;
  const capped = search(maxLegOdds);
  if (capped && !capped.failed) best = capped;
  else capFail = capped;

  // Ha a plafonnal nincs megoldas, feloldjuk. Jobb egy dragabb lab, mint
  // semmi - de a valasz jelzi, hogy ez a szelveny gyenge pontja.
  if (!best) {
    const open = search(Infinity);
    if (open && !open.failed) { best = open; relaxed = true; }
    else if (open && open.failed && !capFail) capFail = open;
  }
  if (best) best.capped_relaxed = relaxed;

  if (!best) {
    if (capFail && capFail.failed === 'target_too_high') {
      return { ok: false, reason: 'target_too_high',
        nMin: capFail.nMin, maxLegs: capFail.maxLegs, maxOdds: capFail.maxOdds };
    }
    // Nincs megoldas minLegs+ labbal - probaljuk egyetlen labbal, mielott
    // a kozelito agra mennenk. Alacsony celnal (pl. 3x) ez a helyes valasz.
    if (minLegs > 1) {
      const single = cand.filter(l => l.tippmix_odds >= lo && l.tippmix_odds <= hi);
      if (single.length) {
        single.sort((a, b) => b.model_prob - a.model_prob);
        return { ok: true, approximate: false, single_leg: true, n: 1,
          legs: [single[0]], prod: single[0].tippmix_odds, jointP: single[0].model_prob };
      }
    }
    // Vegso mentsvar: a teljes jelolt-listan, plafon nelkul.
    const allMaxOdds = Math.max(...cand.map(l => l.tippmix_odds));
    const nMinAll = Math.max(1, Math.ceil(Math.log(T) / Math.log(allMaxOdds)));
    let closest = null;
    for (let n = nMinAll; n <= maxLegs; n++) {
      const greedy = []; const used = new Set(); let prod = 1;
      for (const l of cand) {
        if (greedy.length >= n) break;
        if (used.has(l.event_id)) continue;
        if (prod * l.tippmix_odds > hi && greedy.length) continue;
        greedy.push(l); used.add(l.event_id); prod *= l.tippmix_odds;
      }
      if (greedy.length === n) {
        const d = Math.abs(prod - T);
        if (!closest || d < closest.d) {
          closest = { legs: greedy, prod, n, d, jointP: greedy.reduce((a, l) => a * l.model_prob, 1) };
        }
      }
    }
    if (!closest) return { ok: false, reason: 'no_combination' };
    closest.ok = true; closest.approximate = true;
    return closest;
  }
  best.ok = true; best.approximate = false;
  return best;
}

// ---------- bemenet ----------
const cmd = (() => { try { return $('Verify & Parse').first().json; } catch (e) { return {}; } })();

// KAPU: ha a Verify & Parse mar eldontotte a valaszt (ervenytelen alairas, PING,
// vagy elutasitott felhasznalo), azt valtozatlanul tovabbadjuk. Enelkul a lenti
// szelvenyepito felulirna, es hamis alairasra is 200 menne vissza.
if (cmd.response || cmd.ok === false) {
  return [{ json: {
    message: null,
    response: cmd.response,
    http_status: cmd.http_status || 401,
    gated: true,
  }}];
}
const rows = $input.all().map(i => i.json).filter(r => r && r.leg_id);

const fmt = iso => {
  try {
    return new Date(iso).toLocaleString('hu-HU', { timeZone: 'Europe/Budapest',
      month: 'numeric', day: 'numeric', hour: '2-digit', minute: '2-digit' });
  } catch (e) { return String(iso); }
};
const num = x => Number(x);

// csak a jovobeli meccsek
const now = Date.now();
// Idoablak. A "today" a mai nap VEGEIG szol (helyi ido szerint ejfelig),
// nem 24 orat elore - aki mai meccset ker, a mai naptari napra gondol.
const windowEnd = (() => {
  const wh = cmd.windowHours;
  if (wh === null || wh === undefined) return null;
  if (wh === 'today') {
    const d = new Date();
    // Europe/Budapest ejfel: a helyi datum vege
    const local = new Date(d.toLocaleString('en-US', { timeZone: 'Europe/Budapest' }));
    const endLocal = new Date(local.getFullYear(), local.getMonth(), local.getDate(), 23, 59, 59);
    return now + (endLocal.getTime() - local.getTime());
  }
  return now + wh * 3600000;
})();

const slate = rows.filter(r => {
  const t = new Date(r.kickoff).getTime();
  if (!Number.isFinite(t) || t <= now + 10 * 60000) return false;
  if (windowEnd !== null && t > windowEnd) return false;
  return true;
}).map(r => ({
  ...r,
  model_prob: num(r.model_prob), market_prob: num(r.market_prob),
  tippmix_odds: num(r.tippmix_odds), market_avg_odds: num(r.market_avg_odds),
}));

const HELP = [
  '🎟 SZELVENYEPITO',
  '',
  '/szelveny 10        ~10x osszodds',
  '/szelveny 10 max3   legfeljebb 3 lab',
  '/szelveny 10 min2   labankent min 2.00 odds',
  '/slate              mai kinalat',
  '/help               ez a szoveg',
  '',
  'A rendszer a LEGKEVESEBB labbal eri el a celt, mert a',
  'margo labankent szorzodik: 2 labnal a fair ertek ~86%-a',
  'marad meg, 6 labnal mar csak ~63%-a.',
  '',
  'Egy lab max @5.00 - e folott inkabb egy labbal tobb lesz.',
].join('\n');

let msg;

if (cmd.error) {
  msg = '❓ ' + cmd.error + '\n\n' + HELP;
} else if (cmd.command === 'help') {
  msg = HELP;
} else if (!slate.length) {
  const futureAny = rows.filter(r => new Date(r.kickoff).getTime() > now).length;
  if (cmd.windowHours && futureAny) {
    const label = cmd.windowHours === 'today' ? 'ma' : `${cmd.windowHours} oran belul`;
    msg = `📭 Nincs ${label} kezdodo meccs.\n\n`
        + `A slate-en ${futureAny} kesobbi lab van. Probald idoablak nelkul:\n`
        + `/szelveny cel:${cmd.target || 10}`;
  } else {
    msg = '📭 Ures a slate.\n\n'
        + (rows.length ? `${rows.length} sor van a tablaban, de mind mult ideju.\n` : 'Nincs sor a tablaban.\n')
        + 'A Slate Builder naponta 08:00-kor frissit. Futtasd le kezzel, ha most kell.';
  }
} else if (cmd.command === 'slate') {
  const byMatch = {};
  slate.forEach(l => { (byMatch[l.match_name] = byMatch[l.match_name] || []).push(l); });
  const matches = Object.entries(byMatch)
    .sort((a, b) => new Date(a[1][0].kickoff) - new Date(b[1][0].kickoff))
    .slice(0, 15);
  const lines = matches.map(([m, ls]) => {
    const usable = ls.filter(l => l.confidence !== 'ALACSONY' && l.news_flag !== 'veto');
    const odds = usable.map(l => l.tippmix_odds).sort((a, b) => a - b);
    return `${m}\n   ${fmt(ls[0].kickoff)} · ${ls[0].league}\n   ${usable.length}/${ls.length} hasznalhato lab`
         + (odds.length ? `, odds ${odds[0].toFixed(2)}–${odds[odds.length - 1].toFixed(2)}` : '');
  });
  const usableTotal = slate.filter(l => l.confidence !== 'ALACSONY' && l.news_flag !== 'veto').length;
  const vetoed = slate.filter(l => l.news_flag === 'veto').length;
  msg = `📋 MAI KINALAT — ${matches.length} meccs\n\n${lines.join('\n\n')}\n\n──────────\n`
      + `${usableTotal} hasznalhato lab ${slate.length}-bol`
      + (vetoed ? `\n${vetoed} lab kizarva hir miatt` : '');
} else {
  // /szelveny
  const T = cmd.target;
  const r = buildSlip(slate, {
    target: T,
    maxLegs: cmd.maxLegs || 4,
    minLegOdds: cmd.minLegOdds || 1.30,
  });

  if (!r.ok) {
    const usable = slate.filter(l => l.confidence !== 'ALACSONY' && l.news_flag !== 'veto');
    if (r.reason === 'target_too_high') {
      msg = `⚠️ ${T}x nem erheto el ${r.maxLegs} labbal.\n\n`
          + `A legmagasabb elerheto odds most ${r.maxOdds.toFixed(2)}, ehhez `
          + `legalabb ${r.nMin} lab kellene.\n\n`
          + `Probald: /szelveny ${T} max${Math.min(8, r.nMin)}\n`
          + `De vedd figyelembe: ${r.nMin} labnal a fair ertek kb. `
          + `${(100 / Math.pow(1.08, r.nMin)).toFixed(0)}%-a marad meg.\n\n`
          + `Vagy probalj alacsonyabb celt: /szelveny ${Math.max(2, Math.floor(T / 2))}`;
    } else if (r.reason === 'no_candidates') {
      msg = `📭 Nincs hasznalhato lab.\n\n${slate.length} lab van a slate-en, de egyik sem felelt meg `
          + `a szuronek (min ${cmd.minLegOdds || 1.30} odds, nem ALACSONY bizalom, nincs hir-veto).\n\n`
          + `${usable.length} lab lenne hasznalhato alacsonyabb odds-kuszobbel.`;
    } else {
      msg = `⚠️ Nem talaltam kombinaciot ${T}x celra.\n\nProbalj mas celt vagy tobb labat: /szelveny ${T} max6`;
    }
  } else {
    const prod = r.legs.reduce((a, l) => a * l.tippmix_odds, 1);
    const jointP = r.legs.reduce((a, l) => a * l.model_prob, 1);
    const icon = { MAGAS: '🟢', KOZEPES: '🟡', ALACSONY: '🔴' };
    // Indoklas: miert EZ a lab. A kod harom dolog alapjan valaszt:
    //   1. a modell valoszinusege (ez adja a bejovesi eselyt)
    //   2. a modell-piac egyetertes (MAGAS = megbizhato jel)
    //   3. az odds, hogy a szorzatuk kiadja a celt
    const why = l => {
      const gap = (l.model_prob - l.market_prob) * 100;
      const parts = [];
      if (l.confidence === 'MAGAS') parts.push('a modell es a piac egyetert');
      else if (gap > 0) parts.push(`a modell ${gap.toFixed(0)} ponttal tobbet lat a piacnal`);
      else parts.push(`a piac ${Math.abs(gap).toFixed(0)} ponttal tobbet lat`);
      if (l.model_prob >= 0.5) parts.push('a modell szerint ez a valoszinubb kimenetel');
      return parts.join(', ');
    };
    const blocks = r.legs.map((l, i) =>
      `${i + 1}. ${l.match_name}\n`
      + `   ${fmt(l.kickoff)} · ${l.league}\n`
      + `   ${l.label} @ ${l.tippmix_odds.toFixed(2)}\n`
      + `   modell ${(l.model_prob * 100).toFixed(0)}% · piac ${(l.market_prob * 100).toFixed(0)}% · `
      + `${icon[l.confidence] || ''} ${l.confidence === 'MAGAS' ? 'egyetert' : 'reszben egyetert'}\n`
      + `   ↳ ${why(l)}`
      + (l.news_flag === 'warn' && l.news_note ? `\n   ⚠️ ${l.news_note}` : ''));

    const keep = 100 / Math.pow(1.08, r.n);
    msg = `🎟 SZELVENY — cel ${T}x\n\n${blocks.join('\n\n')}\n\n──────────\n`
        + `Osszodds (becsult): ${prod.toFixed(2)}x`
        + (r.approximate ? '  ⚠️ a cel pontosan nem volt elerheto' : '') + '\n'
        + `Bejovesi esely: ~${(jointP * 100).toFixed(1)}%  (kb. minden ${Math.round(1 / jointP)}. szelveny)\n`
        + (r.single_leg
            ? '1 lab — ez sima fogadas, nem szelveny: ennel a celnal egyetlen\nkimenetel is eleri a kert oddsot.\n\n'
            : `${r.n} lab — kevesebbel a cel nem erheto el\n\n`)
        + `Valasztas: a legmagasabb modell-valoszinusegu labakbol, ahol a\n`
        + `modell es a piac nem mond ellent egymasnak, egy meccsbol egy lab.\n`
        + (r.capped_relaxed
            ? `\n⚠️ Van @5.00 folotti lab. Ez a cel a szokasos plafonnal nem\nvolt elerheto, ezert fel kellett oldani - ez a szelveny gyenge\npontja. Alacsonyabb cellal elkerulheto.\n`
            : `Minden lab @5.00 alatt - nincs szelsoseges ar a szelvenyben.\n`)
        + (cmd.windowHours ? `Idoablak: ${cmd.windowHours === 'today' ? 'csak mai meccsek' : cmd.windowHours + ' oran belul'}\n` : '')
        + `\nA Tippmixpro oddsok BECSULTEK (20 valos aron kalibralva).\n`
        + `Ellenorizd a valos oddsokat leadas elott.\n`
        + `Szelvenynel a margo labankent szorzodik: ${r.n} labnal\n`
        + `a fair ertek kb. ${keep.toFixed(0)}%-a marad meg.`;
  }
}

return [{ json: { message: msg, user_id: cmd.user_id, slate_rows: rows.length, future_rows: slate.length } }];

const j = $json;

// A Verify node mar eldontotte a valasz alakjat a ping / denied / hibas alairas esetekre.
if (j.response) return [{ json: { http_status: j.http_status || 200, response: j.response } }];

// A Discord uzenet limit 2000 karakter.
let content = String(j.message || 'Nincs valasz.');
if (content.length > 1990) content = content.slice(0, 1987) + '...';

return [{ json: {
  http_status: 200,
  response: { type: 4, data: { content } },
}}];
